var a=[{title:`Sensações normais de treino`,text:`Os músculos podem sentir-se quentes, cansados ou a arder durante contrações repetidas. As dores musculares de início tardio podem aparecer um ou dois dias depois de um trabalho pouco habitual. Estas sensações costumam ser diferentes de uma dor súbita em punhalada, de uma articulação que parece instável, de sintomas que se espalham por um membro ou de um desconforto que persiste ou piora mesmo depois de aliviar o esforço.`},{title:`Mais do que um número`,text:`Uma avaliação da dor de 0 a 10 pode descrever a intensidade da dor, mas não consegue dizer a causa. Uma abordagem de semáforo ajuda a ordenar o que sente. Verde é esforço normal com controlo estável. Âmbar é um desconforto invulgar ou crescente e significa parar ou mudar o exercício. Vermelho são sintomas graves ou alarmantes que precisam de avaliação médica.`},{title:`O que fazer`,text:`Pare o movimento que a provoca. Reduza a carga ou a amplitude só se isso for confortável e não continue a tentar de novo para provar que a tolera. Inchaço novo, dormência, fraqueza evidente ou sintomas depois de uma queda precisam de uma avaliação mais atenta. A dor tem muitas causas possíveis, e uma app não consegue dar nome à sua lesão.`},{title:`Exemplo`,text:`Uma sensação de ardor nas coxas perto do fim de uma série de subidas a um degrau é provavelmente esforço muscular. Um joelho que bloqueia de repente com dor, ou em que não consegue apoiar o peso, é outra questão, e alterar o número de repetições não a resolve.`},{title:`Usar o TrainUp`,text:`Se algo doer durante um treino, toque em «Sinto dor». O exercício termina de imediato e fica fora dos seus planos até o retomar no Perfil. Depois de um treino pode indicar dor ou desconforto com a zona do corpo e o exercício, e pode atualizar as suas limitações no Perfil. O TrainUp não dá programas de reabilitação. Consulte um médico ou fisioterapeuta se a dor persistir, for intensa ou o preocupar.`}];var r=[{label:`NHS: dor nas articulações`,url:`https://www.nhs.uk/symptoms/joint-pain/`},{label:`NHS: dor no joelho e quando procurar ajuda`,url:`https://www.nhs.uk/symptoms/knee-pain/`},{label:`NHS: dor lombar e sinais de alerta urgentes`,url:`https://www.nhs.uk/conditions/back-pain/`}];var s={sections:a,sources:r};export{s as default,a as sections,r as sources};